EX = dict(id="nism-vi", series="VI", code="NISM Series VI", short="Depository Operations", title="Depository Operations",
 track="nism-market", tag="VI", level="practitioner",
 blurb="How depositories, depository participants and demat accounts work: opening, transfer, pledge, settlement, corporate actions and debt.",
 intro="NISM Series VI is the certification for people who work in depository operations in India. It covers the securities market and the depository system, the roles of depositories and depository participants (DPs), and every day-to-day DP function: account opening, transmission and nomination, dematerialisation, trading and settlement, pledge, corporate actions, public issues and debt securities. Short units on FPIs, FPIs and basic services demat accounts close the syllabus.",
 who="Staff of depository participants, stock brokers, banks and custodians, back-office and compliance teams, and anyone who wants a clear picture of how securities are held, moved and settled in electronic form.",
 qs=100, mins=120, **{"pass": 60}, pass_=60, neg="25% of marks", marks=100, days=28,
 glance=[["Format", "Computer-based, multiple-choice questions"], ["Questions and marks", "100 questions, 1 mark each, 100 marks"], ["Duration", "2 hours"], ["Passing score", "60 marks (60%)"], ["Negative marking", "25% of a question's marks, so 0.25 per wrong answer"], ["Certificate validity", "Three years; renew through NISM"], ["Where it leads", "Operational roles at depository participants and in depository operations"]],
 checklist=["Re-read units 3, 4 and 7, which carry 12% each.", "Learn the BO ID formats of NSDL and CDSL and the ISIN structure.", "Write out the pledge cycle (create, confirm, invoke, close) from memory.", "Revise the BSDA limits and AMC slabs on one page.", "Take Mock 5 timed, two hours, no breaks."],
 tips=["A wrong answer costs 0.25, so guess only after you have removed two options.", "Learn the sequence of every process: creation, confirmation, execution, closure.", "Keep similar terms apart: pledge versus hypothecation, transmission versus transfer, remat versus demat.", "For 'NOT correct' questions, test each option against its rule.", "Read the settlement cycle and holding-period numbers carefully; they are easy marks."],
 sheet=[("Depository and DP at a glance", [["Item", "Rule"], ["Depository", "Holds securities in electronic form; keeps the record of beneficial owners; works through DPs"], ["Depository participant", "Agent of the depository; opens BO accounts and handles instructions"], ["Beneficial owner (BO)", "The investor who owns the securities; enjoys all rights and benefits"], ["Registered owner", "The depository appears in the issuer's records, but holds for the BO"], ["ISIN", "12-character international security identification number"], ["BO ID (NSDL)", "DP ID of 8 characters starting 'IN' plus 8-digit client ID"], ["BO ID (CDSL)", "16 digits: 8-digit DP ID plus 8-digit client ID"]]),
        ("BSDA snapshot", [["Value of holdings", "Maximum annual maintenance charge"], ["Up to ₹4 lakh", "Nil"], ["Above ₹4 lakh, up to ₹10 lakh", "₹100 plus GST"], ["Above ₹10 lakh", "Not eligible for BSDA"]])],
 units=[
 dict(n=1, title="Introduction to securities market", w=5,
  overview="The market that the depository system serves: what securities are, who issues and trades them, and who regulates the market.",
  focus=["Primary and secondary markets.", "Market participants.", "Role of SEBI.", "Rolling settlement."],
  facts=[("Securities","Securities include shares, debentures, government securities, units of mutual funds and similar instruments that can be issued and traded.","A share of a listed company and a government bond are both securities.","Only shares are securities."),
   ("Primary market","The primary market is where new securities are issued by companies to raise funds directly from investors.","A company launches an initial public offer to raise capital.","The primary market is where existing shares are traded among investors."),
   ("Secondary market","The secondary market is where already-issued securities are bought and sold between investors, on stock exchanges.","An investor sells her listed shares through a broker on an exchange.","The secondary market raises fresh capital for the issuer."),
   ("Stock exchange","A stock exchange provides a platform on which members trade securities under rules and surveillance.","Trades in listed shares are executed on a recognised exchange.","A stock exchange issues shares to the public."),
   ("Clearing corporation","A clearing corporation guarantees and settles trades made on an exchange, managing the obligations of members.","The clearing corporation works out what each broker must pay or deliver.","The clearing corporation holds investors' securities in demat form."),
   ("Rolling settlement","In rolling settlement every trade is settled a fixed number of working days after the trading day; equity trades settle on a T+1 basis.","A share bought on Monday is settled on the next working day.","A weekly account period settles all trades together on Friday."),
   ("Role of SEBI","SEBI regulates the securities market, protects investors and promotes market development.","SEBI frames the rules that depositories and DPs must follow.","SEBI trades securities on behalf of investors."),
   ("Market intermediaries","Intermediaries such as brokers, depository participants, merchant bankers and registrars help investors use the market.","An investor needs a broker to trade and a DP to hold shares.","Investors can trade on an exchange without any intermediary.")]),
 dict(n=2, title="Introduction to depository", w=10,
  overview="Why depositories exist, the law behind them, and how holding securities electronically differs from holding certificates.",
  focus=["Problems of physical securities.", "Depositories Act, 1996.", "NSDL and CDSL.", "Beneficial owner and registered owner."],
  facts=[("Depository","A depository is an organisation that holds securities of investors in electronic form and facilitates their transfer through book entries.","An investor's shares are held as electronic records instead of paper certificates.","A depository is a stock exchange that lists new companies."),
   ("Problems of physical securities","Physical certificates carry risks of loss, theft, forgery, bad delivery and delay in transfer and paperwork.","A certificate lost in transit has to be replaced with effort and cost.","Physical certificates cannot be lost or forged."),
   ("Depositories Act, 1996","The Depositories Act, 1996 provides the legal framework for depositories, dematerialisation and the transfer of securities by book entry.","The Act lets securities be held and transferred without certificates.","The Act applies only to physical securities."),
   ("NSDL and CDSL","India has two depositories, National Securities Depository Limited (NSDL) and Central Depository Services (India) Limited (CDSL).","An investor may open her demat account with a DP linked to either depository.","India has a single depository for all securities."),
   ("Beneficial owner","The beneficial owner (BO) is the person whose name appears in the depository's records as the owner of the securities and who enjoys their benefits.","The investor receives dividends and votes on her demat shares.","The depository enjoys the benefits of securities held by BOs."),
   ("Registered owner","In the issuer's books the depository appears as the registered owner of dematerialised securities but holds them for the beneficial owner.","The company's register shows NSDL as holder of shares held in demat form.","The registered owner has voting rights over the shares."),
   ("Fungibility","Securities held in a depository are fungible, so no distinguishing numbers or certificate marks are kept for individual securities.","Any 10 shares of a company are equal to another 10 shares of the same company.","Each demat share keeps its own distinctive number."),
   ("Benefits of the depository system","Holding in demat form saves time, avoids bad delivery, reduces paperwork, allows trading in single-share lots and speeds up transfer.","An investor can sell a single share without any certificate.","Demat holding makes transfers slower than physical holding."),
   ("Depository versus bank","A depository holds securities of investors just as a bank holds their money, and transfers move by book entry.","Shares move from one demat account to another like money between bank accounts.","A depository pays interest on securities held with it.")]),
 dict(n=3, title="Depository and its business partners", w=12,
  overview="Who the depository works with: depository participants, issuers, registrars, clearing corporations and exchanges, and how DPs are admitted and supervised.",
  focus=["Who can become a DP.", "Depository participant functions.", "Issuer and registrar.", "Clearing corporation and clearing member."],
  facts=[("Depository participant","A depository participant (DP) is an agent of the depository through which investors access depository services, such as opening BO accounts.","A bank branch acts as a DP and opens demat accounts for its customers.","A DP is an agent of the investor and not of the depository."),
   ("Eligibility to be a DP","Entities such as banks, public financial institutions, custodians, clearing corporations, stock brokers, NBFCs and registrars can become DPs, subject to net worth norms and approval.","A SEBI-registered stock broker applies to become a DP.","Any individual can become a DP without registration."),
   ("DP registration","A DP must be registered with SEBI and admitted by the depository, and must meet net worth and other requirements.","A stock broker obtains SEBI registration before acting as a DP.","A DP is registered with the depository only."),
   ("Depository and DP agreement","The DP enters into an agreement with the depository, and the BO enters into an agreement with the DP when opening an account.","A new account holder signs account-opening documents with the DP.","The BO deals directly with the depository and signs nothing with the DP."),
   ("Issuer","An issuer is the company or body that issues securities and may offer them in demat form through the depository.","A listed company makes its shares available in dematerialised form.","The issuer holds securities of BOs."),
   ("Registrar and transfer agent","A registrar and transfer agent maintains the issuer's records and handles share transfers and demat requests for the issuer.","The registrar confirms a demat request and updates the issuer's records.","The registrar opens demat accounts for investors."),
   ("Clearing corporation and clearing member","The clearing corporation settles exchange trades, and clearing members hold accounts with it to settle obligations on behalf of brokers and clients.","A clearing member delivers shares to the clearing corporation on the settlement day.","The clearing corporation deals directly with each investor."),
   ("Inspection and supervision","Depositories inspect DPs, monitor compliance and can take action for violations, and SEBI oversees the system.","The depository audits a DP's records and procedures.","DPs are not subject to inspection."),
   ("Segregation of client assets","A DP must keep investors' securities separate from its own and cannot use client securities for its own benefit.","A broker-DP keeps its own demat account separate from clients' accounts.","A DP may use clients' securities for its own dealings.")]),
 dict(n=4, title="Functions of DP: account opening", w=12,
  overview="How a demat (beneficial owner) account is opened: forms, KYC, documents, types of accounts, statements and closure.",
  focus=["Account opening process.", "KYC and PAN.", "Types of accounts.", "Statements and tariff."],
  facts=[("Beneficial owner account","A beneficial owner (BO) account, or demat account, holds securities in electronic form and is opened with a DP.","An investor opens a demat account with a bank DP.","A demat account can be opened directly with the issuer."),
   ("Account opening form and agreement","The investor completes an account opening form and signs the agreement setting out the rights and obligations of the BO and the DP.","A new client signs the account opening form and the standard rights and obligations document.","A verbal agreement is enough to open a demat account."),
   ("KYC and PAN","Opening an account requires KYC compliance, with PAN, proof of identity and proof of address, and PAN is mandatory.","A client submits her PAN card and address proof with the form.","An account can be opened without PAN."),
   ("Account holder","An investor can hold more than one demat account, with the same or different DPs, and the first holder in a joint account is the primary holder.","A client holds one account for trading and another for long-term holding.","An investor may hold only one demat account in India."),
   ("Types of accounts","Demat accounts may be opened by individuals, joint holders, HUFs, companies, trusts, NRIs and minors through a guardian.","A parent opens a demat account for her minor child as natural guardian.","Only adults acting alone may open demat accounts."),
   ("BO ID","Every account has a unique BO ID: for NSDL a DP ID beginning with 'IN' followed by an 8-digit client ID, and for CDSL a 16-digit ID of DP ID and client ID.","An investor quotes her 16-digit ID in a trade instruction.","The BO ID is the same for all of an investor's accounts."),
   ("Transaction and holding statements","A DP sends a statement of transactions at least monthly when there are transactions, and a statement of holdings at least quarterly otherwise.","An account with trades receives a monthly statement.","A DP need not send any statements."),
   ("Tariff and charges","The DP must disclose its tariff and cannot charge beyond what it has disclosed; it levies charges such as annual maintenance and debit transaction fees.","The tariff sheet lists the annual maintenance charge.","A DP may add hidden charges at its own choice."),
   ("Account closure","A BO can close the account by request after transferring securities, and a DP can close an account only by giving notice to the BO.","A BO moves holdings to another account and closes the first.","A DP can close an account without notice to the BO."),
   ("Power of attorney and DDPI","A BO may authorise a broker or another person to act through a power of attorney or demat debit and pledge instruction, which is optional and must follow SEBI rules.","A client signs a DDPI so her broker can deliver shares for settlement.","A power of attorney is mandatory to open a demat account."),
   ("Change of details","A BO may change address, bank details, signature or nomination by sending a request with supporting documents to the DP.","A client updates her address with fresh proof.","Details cannot be changed after the account is opened.")]),
 dict(n=5, title="Functions of DP: transmission and nomination", w=5,
  overview="What happens to securities on the death of a holder: nomination, transmission, and the documents needed.",
  focus=["Nomination.", "Transmission.", "Joint holders.", "Documents."],
  facts=[("Nomination","Nomination lets an account holder name a person who will receive the securities if the holder dies.","A holder names her son as nominee when opening the account.","A nominee becomes owner of the securities while the holder is alive."),
   ("Number of nominees","SEBI allows an investor to nominate up to ten persons for a demat account, with the percentage share of each specified.","An investor splits holdings among three nominees in stated proportions.","Only one nominee is permitted for a demat account."),
   ("Transmission","Transmission is the transfer of securities to a person by operation of law, such as on the death of a holder, and not by sale or gift.","Securities of a deceased holder pass to the nominee or legal heir.","Transmission is a transfer for consideration."),
   ("Joint holders","On the death of one joint holder, the surviving joint holder is recognised as the holder of the securities.","The second holder continues to hold the securities after the first holder's death.","The securities of a joint account are frozen permanently on a holder's death."),
   ("Documents for transmission","A transmission request needs a claim form, an attested death certificate and identity and KYC details of the claimant, with extra documents when there is no nominee.","The nominee submits the death certificate with her claim.","No documents are required for transmission."),
   ("Nominee and legal heir","A nominee receives the securities as a trustee for the legal heirs when the law provides so, while a legal heir has a right under succession law.","A nominee must account to the legal heirs where succession rules say so.","A nominee always owns the securities outright against other legal heirs."),
   ("Nomination for minors","A nominee may be a minor, with a guardian appointed to act for her.","A holder nominates her grandchild and names the child's guardian.","A minor cannot be a nominee under any circumstance.")]),
 dict(n=6, title="Functions of DP: dematerialisation", w=9,
  overview="Converting physical certificates into electronic holdings and back again.",
  focus=["Demat process.", "Remat.", "ISIN.", "Physical share transfer rules."],
  facts=[("Dematerialisation","Dematerialisation is converting physical securities into electronic form and crediting them to the investor's demat account.","An investor surrenders paper certificates and receives the same shares electronically.","Dematerialisation is converting electronic securities into paper."),
   ("Demat request form","The investor fills a demat request form (DRF) and submits it with the certificates to the DP.","A holder hands over certificates with a DRF.","A DRF is submitted to the stock exchange."),
   ("Defacing certificates","The DP marks the certificates 'Surrendered for dematerialisation' and sends them with the request to the issuer or registrar.","The certificates are stamped so they cannot be used again.","The certificates are returned to the investor after the demat request."),
   ("Role of the registrar in demat","The registrar verifies the request and certificates, cancels them, confirms to the depository, and the depository credits the account.","The registrar confirms and the account is credited with electronic securities.","The DP credits the account before the registrar confirms."),
   ("Rematerialisation","Rematerialisation converts demat holdings back into physical certificates at the investor's request.","A holder asks for paper certificates through a remat request form.","Rematerialisation is the same as dematerialisation."),
   ("ISIN","An ISIN is a unique 12-character international securities identification number, allotted to each security, which begins with 'IN' for Indian securities.","A company's equity shares and its debentures carry different ISINs.","One ISIN applies to all securities of an issuer."),
   ("Physical transfer restriction","SEBI does not permit the transfer of listed securities in physical form, other than for transmission and transposition, so securities must be dematerialised before transfer.","A holder of paper shares must demat before she can sell them.","Physical shares can be transferred freely for any purpose."),
   ("Transposition","Transposition is a change in the order of names of joint holders, and it is done by the issuer or registrar.","Joint holders swap the sequence of their names.","Transposition means a transfer of securities to a new holder."),
   ("Name matching","The names and order on the certificates must match the demat account, and unmatched requests are rejected or need further steps.","A DRF is rejected because the certificate name differs from the account name.","The names on certificates need not match the demat account.")]),
 dict(n=7, title="Functions of DP: trading and settlement", w=12,
  overview="How securities move after a trade: on-market and off-market transfers, delivery instructions, pay-in and pay-out, and the settlement cycle.",
  focus=["Delivery instruction slip.", "On-market and off-market.", "Pay-in and pay-out.", "T+1 settlement."],
  facts=[("Settlement cycle","Equity trades on exchanges settle on a T+1 rolling basis, meaning one working day after the trade day.","A trade made on Tuesday settles on Wednesday.","Equity trades settle on T+5."),
   ("Delivery instruction slip","The BO gives a signed delivery instruction slip (DIS), issued by the DP in a booklet with pre-printed serial numbers, to debit securities from her account.","A client submits a DIS to deliver shares for a sale.","A DIS is used to credit securities to an account."),
   ("Electronic delivery instruction","BOs can give delivery instructions online using e-DIS authorised by a TPIN and one-time password.","A client authorises delivery through the depository's online facility.","Online instructions need no authorisation."),
   ("On-market transfer","An on-market transfer settles a trade executed on a stock exchange, with delivery through the clearing corporation.","A seller's securities move to the clearing corporation for settlement of her trade.","An on-market transfer happens only between two relatives."),
   ("Off-market transfer","An off-market transfer is a transfer of securities directly between two BOs without a trade on an exchange, such as a gift or family transfer.","A father transfers shares to his daughter's account directly.","An off-market transfer settles through the stock exchange's clearing corporation."),
   ("Inter-depository transfer","An inter-depository transfer moves securities between accounts held with different depositories.","A holder shifts shares from an NSDL account to a CDSL account.","Securities cannot be moved between NSDL and CDSL accounts."),
   ("Pay-in and pay-out","Pay-in is the delivery of securities to the clearing corporation by sellers, and pay-out is the delivery of securities from it to buyers.","The seller's DP delivers shares at pay-in and the buyer receives them at pay-out.","Pay-in is the delivery of securities to the buyer."),
   ("Early pay-in","Securities may be delivered at the usual pay-in time or earlier, called early pay-in, and the DP processes instructions before the deadline.","A seller delivers shares a day before the settlement day.","Delivery can be made only on the settlement day itself."),
   ("Failed instructions","An instruction fails if securities are insufficient, the account is frozen or details are wrong, and the DP must tell the BO or correct it.","A delivery fails because the account holds fewer shares than needed.","A failed delivery is carried out anyway."),
   ("Freeze or suspension","A BO or an authority can freeze an account or particular securities, with a debit freeze stopping outgoing transfers and a total freeze stopping both debits and credits.","A debit freeze stops sales but allows credits.","A debit freeze blocks both credits and debits."),
   ("Settlement guarantee and risk","The clearing corporation guarantees the settlement of exchange trades, which lowers counterparty risk.","The buyer is protected if the seller defaults on delivery.","Settlement of exchange trades is not guaranteed by anyone.")]),
 dict(n=8, title="Functions of DP: pledge and hypothecation", w=10,
  overview="Using securities as collateral for loans and margins, while they stay in demat form.",
  focus=["Pledge cycle.", "Hypothecation.", "Margin pledge.", "Invocation and closure."],
  facts=[("Pledge","A pledge is the delivery of securities as security for a loan, with the pledged securities blocked in the borrower's account.","A borrower pledges shares to a bank for a loan.","In a pledge the lender never holds any claim on the securities."),
   ("Pledgor and pledgee","The pledgor is the borrower who pledges the securities and the pledgee is the lender who accepts them as security.","The bank is the pledgee and the borrower is the pledgor.","The pledgee is the owner who offers the securities."),
   ("Pledge creation and confirmation","The pledgor requests the pledge through her DP and the pledgee confirms it, so the pledge is created only after confirmation.","A pledge becomes effective after the lender confirms it.","A pledge is complete when the pledgor submits the request."),
   ("Pledge closure","When the loan is repaid, the pledgee closes the pledge, or both parties request closure, and the securities are released.","After repayment, the bank closes the pledge.","The pledgor can close a pledge alone without the pledgee's consent."),
   ("Invocation","If the pledgor defaults, the pledgee can invoke the pledge, and securities are moved to the pledgee's account.","The lender invokes the pledge after repeated default.","The pledgor invokes a pledge when she wants her shares back."),
   ("Rights of the pledgor","While securities are pledged, the pledgor continues to enjoy corporate benefits such as dividends, as the pledgor remains the beneficial owner.","A borrower still receives a dividend on pledged shares.","The pledgee receives all corporate benefits throughout the pledge."),
   ("Hypothecation","In a hypothecation, the securities remain in the borrower's account but are blocked in favour of the lender, who gets a charge without possession.","A borrower hypothecates shares to a bank, which holds a charge on them.","In hypothecation the lender takes the securities into its own account."),
   ("Margin pledge","Clients give securities as margin to brokers by creating a margin pledge in favour of the clearing member, and the clearing member may re-pledge them to the clearing corporation.","A client pledges shares as margin for derivatives positions.","Clients must transfer shares to the broker's own account to give margin."),
   ("Restrictions on pledged securities","Pledged securities cannot be sold or transferred until the pledge is closed or invoked, and any partial release is handled by the pledgee.","A client must first release the pledge before selling the shares.","Pledged shares can be sold freely by the pledgor.")]),
 dict(n=9, title="Functions of DP: corporate actions", w=5,
  overview="How benefits like dividends, bonus and splits reach demat accounts.",
  focus=["Record date.", "Cash and non-cash benefits.", "Rights and buyback."],
  facts=[("Corporate action","A corporate action is an event by an issuer, such as a dividend, bonus, split, rights issue or merger, that affects securities and holders.","A company announces a bonus issue to its shareholders.","A corporate action is a trade between two investors."),
   ("Record date","The record date is the date on which a holder must be on the company's records to be entitled to the benefit.","A holder on the record date receives the dividend.","The record date is the date the benefit is paid."),
   ("Cash benefits","Cash benefits such as dividends are paid directly to the BO's bank account, using details held by the depository or issuer.","A dividend is credited to the shareholder's bank account.","Dividends are credited as securities to the demat account."),
   ("Non-cash benefits","Non-cash benefits such as bonus shares and split shares are credited to the demat account of the BO, using fresh ISINs where needed.","Bonus shares appear in the demat account.","Bonus shares are paid by cheque."),
   ("Stock split","A stock split reduces the face value of a share and increases the number of shares held, without changing total value.","A ₹10 share is split into two shares of ₹5 each.","A split reduces the number of shares held."),
   ("Rights issue","In a rights issue, existing shareholders get the right to subscribe to new shares in proportion to their holdings.","A holder is offered one new share for every four held.","A rights issue is open only to new investors."),
   ("Buyback","In a buyback the company purchases its own shares from holders, and the shares tendered are debited from the BO's account.","A holder tenders her shares in the company's offer.","A buyback adds new shares to holders' accounts.")]),
 dict(n=10, title="Functions of DP: public issues", w=5,
  overview="How investors apply for public issues and receive shares in the demat account.",
  focus=["IPO in demat.", "ASBA and UPI.", "Allotment and credit.", "Role of the DP."],
  facts=[("Public issue","A public issue is an offer of securities to the public by a company for subscription, such as an initial public offer.","A company offers new shares to investors at a price band.","A public issue is the sale of existing shares on the exchange."),
   ("Initial public offer","An initial public offer (IPO) is the first public offer of shares by an unlisted company, and its securities are issued in dematerialised form.","An investor applies for shares in an IPO and receives them in her account.","Allotment in an IPO is made in paper certificates only."),
   ("Demat account for applicants","An applicant in a public issue needs a demat account, and the allotment is credited to it.","An investor quotes her DP ID and client ID in the application.","An investor needs no demat account to apply in a public issue."),
   ("ASBA","Application Supported by Blocked Amount (ASBA) blocks the application money in the investor's bank account until allotment, instead of debiting it.","The amount remains in the investor's account, blocked, while the bid is pending.","Under ASBA the money is paid out at the time of application."),
   ("Demat credit on allotment","Securities allotted to successful applicants are credited to their demat accounts through the registrar and depository, and the unallotted amount is released.","The allotted shares appear in the account before listing.","Allotted shares are posted to the investor days after listing."),
   ("Mismatch of details","If the name or details in the application differ from the demat records, allotment can fail or be delayed, so details must match.","An application with the wrong client ID is rejected.","Mismatched details never affect the allotment.")]),
 dict(n=11, title="Functions of DP: debt and government securities", w=10,
  overview="Holding and trading debt securities and government securities in electronic form.",
  focus=["Government securities.", "Treasury bills.", "Debt in demat.", "Retail Direct."],
  facts=[("Debt securities","Debt securities such as debentures and bonds are instruments by which an issuer borrows and pays interest, and can be held in demat form.","An investor holds a corporate bond in her demat account.","Debt securities represent ownership in the issuer."),
   ("Government securities","Government securities (G-secs) are debt instruments issued by the central or state governments, and they carry the lowest credit risk.","A dated government security pays a fixed coupon every half-year.","Government securities are issued by private companies."),
   ("Treasury bills","Treasury bills are short-term government securities issued at a discount and redeemed at face value, with maturities of 91, 182 and 364 days.","An investor buys a 91-day bill below face value and receives face value on maturity.","Treasury bills pay a coupon every six months."),
   ("SGL account","A Subsidiary General Ledger (SGL) account with the RBI holds government securities in electronic form for eligible institutions.","A bank holds its government securities in an SGL account.","An SGL account is held by retail investors with a DP."),
   ("Constituent SGL","A Constituent SGL (CSGL) account lets a constituent hold government securities through a bank or institution that has an SGL account.","A small institution holds government securities through its bank's SGL facility.","A CSGL account is the same as a demat account with CDSL."),
   ("Retail access to G-secs","Retail investors can invest in government securities through demat accounts with a DP or through the RBI Retail Direct facility.","A retail investor buys a T-bill online.","Retail investors are barred from holding government securities."),
   ("Commercial paper and debt in demat","Money market instruments such as commercial paper are issued in dematerialised form.","A company's commercial paper is credited to the holder's demat account.","Commercial paper may be issued only in paper form."),
   ("Coupon and maturity","A debt security pays periodic interest, the coupon, and returns the face value on maturity, handled as a corporate action by the depository.","On maturity the redemption proceeds are paid to the holder.","A debt security never repays the principal."),
   ("Settlement of debt trades","Debt trades are settled through clearing corporations, with securities moved between demat accounts on a delivery versus payment basis.","Securities and cash change hands together on settlement.","Debt trades are settled by physical delivery.")]),
 dict(n=12, title="Additional services: FPI and basic services demat account", w=5,
  overview="Two smaller topics: how foreign portfolio investors hold securities, the Rajiv Gandhi Equity Savings Scheme, and the low-cost basic services demat account.",
  focus=["FPI holding limits.", "BSDA eligibility and charges."],
  facts=[("Foreign portfolio investor","A foreign portfolio investor (FPI) is a registered foreign investor who invests in Indian securities through a demat account with a DP, and who must be registered through a designated depository participant.","A foreign fund registers and opens a demat account to invest in listed shares.","An FPI may invest without registration or a demat account."),
   ("FPI investment limits","A single FPI can hold up to 10% of the paid-up capital of a company, and the combined holding of all FPIs is limited to 24%, which can be raised up to the sectoral cap.","A fund keeps its stake in a company below 10%.","An FPI may hold any proportion of a company."),
   ("Basic services demat account","A basic services demat account (BSDA) is a low-cost demat account for small investors with limited holdings, and an investor can hold only one BSDA.","A small investor opens a BSDA to hold a few shares.","An investor may hold several BSDAs across depositories."),
   ("BSDA eligibility","A BSDA is meant for an individual with only one demat account in her name, and the value of securities in it must not exceed ₹10 lakh.","An investor with holdings of ₹6 lakh qualifies for a BSDA.","A BSDA is available for holdings of any value."),
   ("BSDA charges","For a BSDA, the annual maintenance charge is nil for holdings up to ₹4 lakh and up to ₹100 plus GST for holdings above ₹4 lakh and up to ₹10 lakh.","An account with ₹3 lakh pays no annual maintenance charge.","A BSDA pays the same annual maintenance charge as any other account.")]),
])
